//! Shared threshold tiles generated by prototype/make_golden.py (stored as ranks so
//! Rust and Python use bit-identical thresholds).

use std::sync::OnceLock;

use crate::screen::Tile;

static BN_RAW: &[u8] = include_bytes!("../assets/blue_noise_128.u16");
static G_HALUS: &[u8] = include_bytes!("../assets/green_noise_512_halus.u32");
static G_SEDANG: &[u8] = include_bytes!("../assets/green_noise_512_sedang.u32");
static G_KASAR: &[u8] = include_bytes!("../assets/green_noise_512_kasar.u32");

/// void-and-cluster blue noise 128 x 128 (FM clusters)
pub fn blue_noise() -> &'static Tile {
    static T: OnceLock<Tile> = OnceLock::new();
    T.get_or_init(|| {
        let data = BN_RAW
            .chunks_exact(2)
            .map(|b| ((u16::from_le_bytes([b[0], b[1]]) as f64 + 0.5) / 16384.0) as f32)
            .collect();
        Tile { s: 128, data }
    })
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum Grain {
    Halus,
    Sedang,
    Kasar,
}

fn decode_u32(raw: &[u8]) -> Tile {
    let data = raw
        .chunks_exact(4)
        .map(|b| ((u32::from_le_bytes([b[0], b[1], b[2], b[3]]) as f64 + 0.5) / 262144.0) as f32)
        .collect();
    Tile { s: 512, data }
}

/// band-pass "green noise" 512 x 512 (grain pattern)
pub fn green_noise(g: Grain) -> &'static Tile {
    static H: OnceLock<Tile> = OnceLock::new();
    static S: OnceLock<Tile> = OnceLock::new();
    static K: OnceLock<Tile> = OnceLock::new();
    match g {
        Grain::Halus => H.get_or_init(|| decode_u32(G_HALUS)),
        Grain::Sedang => S.get_or_init(|| decode_u32(G_SEDANG)),
        Grain::Kasar => K.get_or_init(|| decode_u32(G_KASAR)),
    }
}
